create extension if not exists pgcrypto;
create type public.organization_role as enum ('owner','manager','rep');
create type public.session_status as enum ('active','completed','evaluating','evaluated','failed');
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, created_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now());
create table public.memberships (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role organization_role not null, created_at timestamptz not null default now(), unique(organization_id,user_id));
create table public.products (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null, description text not null default '', created_at timestamptz not null default now());
create table public.personas (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null, structured_data jsonb not null default '{}', created_at timestamptz not null default now());
create table public.knowledge_sources (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null, storage_path text, status text not null default 'pending', created_at timestamptz not null default now());
create table public.playbooks (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null, content jsonb not null default '{}', created_at timestamptz not null default now());
create table public.scenarios (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, title text not null, status text not null default 'draft', created_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table public.scenario_versions (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, scenario_id uuid not null references public.scenarios(id) on delete cascade, version integer not null, scenario_spec jsonb not null, source text not null default 'manager', approved_by uuid references auth.users(id), published_at timestamptz, idempotency_key text, created_at timestamptz not null default now(), unique(scenario_id,version), unique(organization_id,idempotency_key));
create table public.assignments (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, scenario_version_id uuid not null references public.scenario_versions(id), created_by uuid not null references auth.users(id), due_at timestamptz, status text not null default 'active', created_at timestamptz not null default now());
create table public.assignment_targets (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, assignment_id uuid not null references public.assignments(id) on delete cascade, user_id uuid not null references auth.users(id), created_at timestamptz not null default now(), unique(assignment_id,user_id));
create table public.sessions (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, scenario_version_id uuid not null references public.scenario_versions(id), user_id uuid not null references auth.users(id), status session_status not null default 'active', started_at timestamptz not null default now(), completed_at timestamptz, completion_key text, created_at timestamptz not null default now(), unique(organization_id,completion_key));
create table public.session_turns (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, session_id uuid not null references public.sessions(id) on delete cascade, sequence integer not null, role text not null check(role in ('seller','buyer')), content text not null, idempotency_key text, created_at timestamptz not null default now(), unique(session_id,sequence), unique(session_id,idempotency_key));
create table public.session_events (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, session_id uuid not null references public.sessions(id) on delete cascade, type text not null, data jsonb not null default '{}', created_at timestamptz not null default now());
create table public.prompt_versions (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, responsibility text not null, version text not null, content_hash text not null, created_at timestamptz not null default now());
create table public.evaluations (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, session_id uuid not null references public.sessions(id) on delete cascade, scenario_version_id uuid not null references public.scenario_versions(id), rubric_version text not null, evaluator_model text not null, evaluator_prompt_version text not null, result jsonb not null, weighted_score integer check(weighted_score between 0 and 100), status text not null, idempotency_key text not null, created_at timestamptz not null default now(), unique(session_id), unique(organization_id,idempotency_key));
create table public.usage_events (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid references auth.users(id), session_id uuid references public.sessions(id), scenario_version_id uuid references public.scenario_versions(id), operation_type text not null, model text not null, input_tokens integer, output_tokens integer, audio_seconds numeric, latency_ms integer, estimated_cost_usd numeric, created_at timestamptz not null default now());
create table public.manager_score_overrides (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, evaluation_id uuid not null references public.evaluations(id), criterion_id text, replacement_score integer not null check(replacement_score between 0 and 4), rationale text not null check(length(rationale)>=10), manager_id uuid not null references auth.users(id), created_at timestamptz not null default now());
create index memberships_user_idx on public.memberships(user_id); create index scenarios_org_idx on public.scenarios(organization_id,created_at desc); create index versions_scenario_idx on public.scenario_versions(scenario_id,created_at desc); create index sessions_org_user_idx on public.sessions(organization_id,user_id,created_at desc); create index turns_session_idx on public.session_turns(session_id,sequence); create index evaluations_session_idx on public.evaluations(session_id,created_at desc); create index usage_org_created_idx on public.usage_events(organization_id,created_at desc);
create function public.is_org_member(org uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.memberships m where m.organization_id=org and m.user_id=(select auth.uid())) $$;
create function public.has_org_role(org uuid, roles organization_role[]) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.memberships m where m.organization_id=org and m.user_id=(select auth.uid()) and m.role=any(roles)) $$;
do $$ declare t text; begin foreach t in array array['organizations','memberships','products','personas','knowledge_sources','playbooks','scenarios','scenario_versions','assignments','assignment_targets','sessions','session_turns','session_events','prompt_versions','evaluations','usage_events','manager_score_overrides'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy tenant_select on public.%I for select using (public.is_org_member(organization_id))',t); end loop; end $$;
create policy profile_self on public.profiles for all using ((select auth.uid())=id) with check ((select auth.uid())=id);
create rule immutable_published_version as on update to public.scenario_versions where old.published_at is not null do instead nothing;
